-- UOM CCT 260/75 · estructura completa y escalas agosto 2026.
BEGIN;

ALTER TABLE public.novedad_mensual ADD COLUMN IF NOT EXISTS uom_detalle jsonb NOT NULL DEFAULT '{}'::jsonb;
ALTER TABLE public.novedad_mensual DROP CONSTRAINT IF EXISTS uom_detalle_objeto;
ALTER TABLE public.novedad_mensual ADD CONSTRAINT uom_detalle_objeto CHECK (jsonb_typeof(uom_detalle)='object');

VALUES (gen_random_uuid(),'260/75','Metalúrgicos','UOMRA',0,0,12,200,false,false,true)
ON CONFLICT (numero) DO UPDATE SET nombre=EXCLUDED.nombre,sindicato=EXCLUDED.sindicato,activo=true;

UPDATE public.cct_categoria SET activa=false WHERE cct_numero='260/75';

ON CONFLICT (cct_numero,codigo,version) DO UPDATE SET nombre=EXCLUDED.nombre,orden=EXCLUDED.orden,activa=true,fuente=EXCLUDED.fuente,estado_fuente=EXCLUDED.estado_fuente,is_verified=true;

-- Sustituye únicamente la carga incompleta del mismo período; no toca historia anterior.
DELETE FROM public.escala_salarial WHERE cct_numero='260/75' AND valid_from=DATE '2026-08-01';


DELETE FROM public.parametro_legal WHERE cct_numero='260/75' AND valid_from=DATE '2026-08-01';


ON CONFLICT (cct_numero,codigo,version) DO UPDATE SET descripcion=EXCLUDED.descripcion,configuracion=EXCLUDED.configuracion,fuente=EXCLUDED.fuente,estado_fuente=EXCLUDED.estado_fuente,is_verified=true,activa=true;

COMMIT;
